package hoard

import (
	"bufio"
	"os"
	"strings"
	"testing"
)

// TestCanonGolden pins the Go port to the Python reference implementation
// (.claude/skills/hoard-viewer-profile/scripts/catalogue_media.py in this repo).
// The golden file is generated by running the Python script's functions over
// canon_paths.txt — regenerate both together if the canonicaliser changes.
func TestCanonGolden(t *testing.T) {
	f, err := os.Open("testdata/canon_golden.tsv")
	if err != nil {
		t.Fatalf("open golden file: %v", err)
	}
	defer f.Close()

	generic := defaultGenericSet(nil)
	scanner := bufio.NewScanner(f)
	line := 0
	for scanner.Scan() {
		line++
		fields := strings.Split(scanner.Text(), "\t")
		if len(fields) != 3 {
			t.Fatalf("golden line %d: expected 3 tab-separated fields, got %d", line, len(fields))
		}
		path, wantTitle, wantKey := fields[0], fields[1], fields[2]
		t.Run(path, func(t *testing.T) {
			got := candidateFromPath(path, generic)
			if got != wantTitle {
				t.Errorf("candidateFromPath(%q) = %q, want %q", path, got, wantTitle)
			}
			if key := normKey(got); key != wantKey {
				t.Errorf("normKey(%q) = %q, want %q", got, key, wantKey)
			}
		})
	}
	if err := scanner.Err(); err != nil {
		t.Fatalf("read golden file: %v", err)
	}
	if line == 0 {
		t.Fatal("golden file is empty")
	}
}

func TestNormKey(t *testing.T) {
	cases := map[string]string{
		"Sapphire & Steel":  "sapphire and steel",
		"Äkta människor":    "akta manniskor",
		"  The  Prisoner  ": "the prisoner",
		"GBH!":              "gbh",
		"":                  "",
	}
	for input, want := range cases {
		if got := normKey(input); got != want {
			t.Errorf("normKey(%q) = %q, want %q", input, got, want)
		}
	}
}

func TestGenericTitle(t *testing.T) {
	generic := defaultGenericSet([]string{"usbdrive01"})
	for _, text := range []string{"TV", "scifi", "Sci Fi", "usbdrive01", "sda1", "42", "ep", "episode 3", ""} {
		if !genericTitle(text, generic) {
			t.Errorf("genericTitle(%q) = false, want true", text)
		}
	}
	for _, text := range []string{"The Sandbaggers", "GBH", "Sky"} {
		if genericTitle(text, generic) {
			t.Errorf("genericTitle(%q) = true, want false", text)
		}
	}
}

func TestMediaTypeForExt(t *testing.T) {
	cases := map[string]string{
		".mkv": "video", ".ts": "video", ".mp3": "audio",
		".srt": "other", "": "other",
	}
	for ext, want := range cases {
		if got := mediaTypeForExt(ext); got != want {
			t.Errorf("mediaTypeForExt(%q) = %q, want %q", ext, got, want)
		}
	}
}
